function(container, apiUrl, tables) {
  let currentOrders = [];
  let selectedOrderIds = new Set();

  // 今日の日付を表示
  const today = new Date().toLocaleDateString('ja-JP');
  container.querySelector('#order-date').textContent = today;

  // 店舗データを読み込んでプルダウンに設定
  async function loadStores() {
    const storeTableIndex = tables.findIndex(t => t.tableName === '店舗マスタ');
    if (storeTableIndex >= 0) {
      const stores = await window.aivicApi.list(storeTableIndex);
      if (stores) {
        const storeSelect = container.querySelector('#store-select');
        stores.forEach(store => {
          if (store.有効フラグ) {
            const option = document.createElement('option');
            option.value = store.id;
            option.textContent = `${store.店舗コード} - ${store.店舗名}`;
            storeSelect.appendChild(option);
          }
        });
      }
    }
  }

  // 発注データ一覧を描画
  function renderOrderList(orders) {
    const tbody = container.querySelector('#order-list-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted); padding: 40px;">発注対象のデータがありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const isSelected = selectedOrderIds.has(order.id);
      const statusBadge = getStatusBadge(order.発注ステータス);
      const isDisabled = order.発注ステータス === '送信済み' || order.発注ステータス === '納品済';

      return `
        <tr data-id="${order.id}" ${isDisabled ? 'style="opacity: 0.6;"' : ''}>
          <td>
            <input type="checkbox" class="order-checkbox" data-id="${order.id}" 
                   ${isSelected ? 'checked' : ''} ${isDisabled ? 'disabled' : ''} />
          </td>
          <td>${order.商品コード || ''}</td>
          <td>${order.商品名 || ''}</td>
          <td style="text-align: right;">${order.予測数量 || 0}</td>
          <td style="text-align: right;">${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || ''}</td>
          <td style="text-align: right;">¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>${statusBadge}</td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // ステータスバッジを生成
  function getStatusBadge(status) {
    const badges = {
      '発注済': '<span style="background: #2196f3; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">発注済</span>',
      '送信済み': '<span style="background: #4caf50; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">送信済み</span>',
      '納品済': '<span style="background: #9e9e9e; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">納品済</span>',
      'キャンセル': '<span style="background: #f44336; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">キャンセル</span>'
    };
    return badges[status] || `<span style="background: #ff9800; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">${status}</span>`;
  }

  // 合計金額を更新
  function updateTotalAmount() {
    const selectedOrders = currentOrders.filter(order => selectedOrderIds.has(order.id));
    const total = selectedOrders.reduce((sum, order) => sum + (order.発注金額 || 0), 0);
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // エラーメッセージを表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    container.querySelector('#success-message').classList.add('hidden');
  }

  // 成功メッセージを表示
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    container.querySelector('#error-message').classList.add('hidden');
  }

  // メッセージを非表示
  function hideMessages() {
    container.querySelector('#error-message').classList.add('hidden');
    container.querySelector('#success-message').classList.add('hidden');
  }

  // 店舗選択時の処理
  container.querySelector('#store-select').addEventListener('change', async function() {
    const storeId = this.value;
    hideMessages();
    selectedOrderIds.clear();

    if (!storeId) {
      currentOrders = [];
      renderOrderList([]);
      return;
    }

    try {
      const orderTableIndex = tables.findIndex(t => t.tableName === '発注データ');
      const productTableIndex = tables.findIndex(t => t.tableName === '商品マスタ');
      const demandTableIndex = tables.findIndex(t => t.tableName === '需要予測結果');

      if (orderTableIndex >= 0) {
        const allOrders = await window.aivicApi.list(orderTableIndex);
        const products = productTableIndex >= 0 ? await window.aivicApi.list(productTableIndex) : [];
        const demands = demandTableIndex >= 0 ? await window.aivicApi.list(demandTableIndex) : [];

        if (allOrders) {
          // 選択した店舗の発注データをフィルタリング
          const storeOrders = allOrders.filter(order => order.店舗ID === storeId);

          // 商品情報と需要予測情報を結合
          currentOrders = storeOrders.map(order => {
            const product = products.find(p => p.id === order.商品ID);
            const demand = demands.find(d => d.商品ID === order.商品ID && d.店舗ID === storeId);

            return {
              ...order,
              商品コード: product?.商品コード || '',
              商品名: product?.商品名 || '',
              仕入先名: product?.仕入先名 || '',
              予測数量: demand?.予測数量 || 0
            };
          });

          renderOrderList(currentOrders);
        }
      }
    } catch (error) {
      showError('発注データの取得に失敗しました');
    }
  });

  // 全選択チェックボックスの処理
  container.querySelector('#select-all').addEventListener('change', function() {
    const isChecked = this.checked;
    const checkboxes = container.querySelectorAll('.order-checkbox:not([disabled])');

    checkboxes.forEach(checkbox => {
      checkbox.checked = isChecked;
      const orderId = checkbox.dataset.id;
      if (isChecked) {
        selectedOrderIds.add(orderId);
      } else {
        selectedOrderIds.delete(orderId);
      }
    });

    updateTotalAmount();
  });

  // 個別チェックボックスの処理
  container.addEventListener('change', function(e) {
    if (e.target.classList.contains('order-checkbox')) {
      const orderId = e.target.dataset.id;
      if (e.target.checked) {
        selectedOrderIds.add(orderId);
      } else {
        selectedOrderIds.delete(orderId);
      }

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.order-checkbox:not([disabled])');
      const checkedCheckboxes = container.querySelectorAll('.order-checkbox:not([disabled]):checked');
      const selectAllCheckbox = container.querySelector('#select-all');

      if (checkedCheckboxes.length === 0) {
        selectAllCheckbox.indeterminate = false;
        selectAllCheckbox.checked = false;
      } else if (checkedCheckboxes.length === allCheckboxes.length) {
        selectAllCheckbox.indeterminate = false;
        selectAllCheckbox.checked = true;
      } else {
        selectAllCheckbox.indeterminate = true;
      }

      updateTotalAmount();
    }
  });

  // 送信ボタンの処理
  container.querySelector('#btn-send-selected').addEventListener('click', function() {
    hideMessages();

    if (selectedOrderIds.size === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    // 送信済みデータの重複チェック
    const selectedOrders = currentOrders.filter(order => selectedOrderIds.has(order.id));
    const alreadySent = selectedOrders.filter(order => 
      order.発注ステータス === '送信済み' || order.発注ステータス === '納品済'
    );

    if (alreadySent.length > 0) {
      showError('選択した発注データに送信済みのものが含まれています。重複送信はできません。');
      return;
    }

    // 発注数量0の商品チェック
    const zeroQuantityOrders = selectedOrders.filter(order => (order.発注数量 || 0) === 0);
    if (zeroQuantityOrders.length > 0) {
      showError('発注数量が0の商品が含まれています。発注数量を確認してください。');
      return;
    }

    // 確認ダイアログを表示
    container.querySelector('#selected-count').textContent = selectedOrderIds.size;
    container.querySelector('#send-confirm-dialog').classList.remove('hidden');
  });

  // 送信確認ダイアログのキャンセル
  container.querySelector('#btn-cancel-send').addEventListener('click', function() {
    container.querySelector('#send-confirm-dialog').classList.add('hidden');
  });

  // 送信実行
  container.querySelector('#btn-confirm-send').addEventListener('click', async function() {
    container.querySelector('#send-confirm-dialog').classList.add('hidden');

    try {
      const orderTableIndex = tables.findIndex(t => t.tableName === '発注データ');
      let successCount = 0;
      let failCount = 0;

      // ネットワークエラーのシミュレーション（オフライン状態チェック）
      if (!navigator.onLine) {
        showError('ネットワークエラーが発生しました。接続を確認して再度お試しください。');
        return;
      }

      for (const orderId of selectedOrderIds) {
        try {
          const updated = await window.aivicApi.update(orderTableIndex, orderId, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString()
          });

          if (updated) {
            successCount++;
          } else {
            failCount++;
          }
        } catch (error) {
          failCount++;
        }
      }

      if (failCount === 0) {
        showSuccess(`${successCount}件の発注データを正常に送信しました`);
      } else {
        showError(`送信処理が完了しました。成功: ${successCount}件、失敗: ${failCount}件`);
      }

      // データを再読み込み
      const storeId = container.querySelector('#store-select').value;
      if (storeId) {
        container.querySelector('#store-select').dispatchEvent(new Event('change'));
      }

      selectedOrderIds.clear();

    } catch (error) {
      showError('送信処理中にエラーが発生しました');
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', async function() {
    if (currentOrders.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    try {
      const headers = ['商品コード', '商品名', '予測需要数量', '発注数量', '仕入先名', '発注金額', '送信ステータス'];
      const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
        currentOrders.map(order => [
          order.商品コード || '',
          `"${(order.商品名 || '').replace(/"/g, '""')}"`,
          order.予測数量 || 0,
          order.発注数量 || 0,
          `"${(order.仕入先名 || '').replace(/"/g, '""')}"`,
          order.発注金額 || 0,
          order.発注ステータス || ''
        ].join(',')).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注送信データ_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

      showSuccess('CSVファイルをダウンロードしました');
    } catch (error) {
      showError('CSVエクスポートに失敗しました');
    }
  });

  // 初期化
  loadStores();
}
